import { test } from 'node:test';
import assert from 'node:assert/strict';
import create from '../src/host.impl.ts';

test('starts follower term 0', async () => {
  const h = await create();
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
});

test('election flow', async () => {
  const h = await create();
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.quorumLost()).ok, false);
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, true);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionWon()).ok, true);
  assert.deepEqual(await h.node(), { role: 'leader', term: 2, votedFor: 'itself' });
  assert.equal((await h.electionTimeout()).ok, false);
  assert.equal((await h.quorumLost()).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'itself' });
  assert.equal((await h.voteRequested('n1', 2)).ok, false);
  assert.equal((await h.electionTimeout()).ok, true);
  assert.equal((await h.electionTimeout()).ok, false);
  assert.deepEqual(await h.node(), { role: 'candidate', term: 3, votedFor: 'itself' });
});

test('newer term', async () => {
  const h = await create();
  assert.equal((await h.newerTermSeen(0)).ok, false);
  assert.equal((await h.newerTermSeen(4)).ok, false);
  assert.equal((await h.newerTermSeen(1.5)).ok, false);
  await h.electionTimeout();
  assert.equal((await h.newerTermSeen(2)).ok, true);
  assert.equal((await h.newerTermSeen(2)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'nobody' });
});

test('votes', async () => {
  const h = await create();
  assert.equal((await h.voteRequested('n3', 1)).ok, false);
  assert.equal((await h.voteRequested('n1', 0)).ok, false);
  assert.equal((await h.voteRequested('n1', 4)).ok, false);
  assert.deepEqual(await h.node(), { role: 'follower', term: 0, votedFor: 'nobody' });
  await h.electionTimeout();
  assert.equal((await h.voteRequested('n1', 1)).ok, false); // candidate in same term
  assert.equal((await h.voteRequested('n1', 2)).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 2, votedFor: 'n1' });
  assert.equal((await h.voteRequested('n1', 2)).ok, true);
  assert.equal((await h.voteRequested('n2', 2)).ok, false);
  assert.equal((await h.voteRequested('n2', 1)).ok, false);
  assert.equal((await h.newerTermSeen(3)).ok, true);
  assert.equal((await h.voteRequested('n2', 3)).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'n2' });
});

test('leader refuses same-term vote, grants newer', async () => {
  const h = await create();
  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.equal((await h.voteRequested('n1', 3)).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 3, votedFor: 'n1' });
});

test('election lost', async () => {
  const h = await create();
  assert.equal((await h.electionLost()).ok, false);
  await h.electionTimeout();
  assert.equal((await h.electionLost()).ok, true);
  assert.deepEqual(await h.node(), { role: 'follower', term: 1, votedFor: 'itself' });
  assert.equal((await h.electionLost()).ok, false);
  assert.equal((await h.electionWon()).ok, false);
  assert.equal((await h.voteRequested('n1', 1)).ok, false);
  assert.equal((await h.voteRequested('n1', 2)).ok, true);
  await h.electionTimeout();
  await h.electionWon();
  assert.equal((await h.electionLost()).ok, false);
  await h.shutdown();
  assert.equal((await h.electionLost()).ok, false);
});

test('shutdown', async () => {
  const h = await create();
  await h.electionTimeout();
  assert.equal((await h.shutdown()).ok, true);
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
  for (const r of [await h.shutdown(), await h.electionTimeout(), await h.electionWon(), await h.newerTermSeen(3), await h.quorumLost(), await h.voteRequested('n1', 3)]) {
    assert.equal(r.ok, false);
  }
  assert.deepEqual(await h.node(), { role: 'shutdown', term: 1, votedFor: 'itself' });
});

